// Step 2: Commercial Floor & Rubric Scoring Engine
const body = $input.first().json.body || $input.first().json;

const domain = (body.domain || '').trim().toLowerCase();
const budgetUsd = Number(body.estimated_budget_usd || body.deal_value || 0);
const teamSize = Number(body.team_size || 1);
const hasDigitalPresence = Boolean(body.has_website || domain);
const healthScore = Number(body.overall_health_score || 70);

// Non-negotiable Agency OS rule: $500 Commercial Floor
const COMMERCIAL_FLOOR_USD = 500;
if (budgetUsd > 0 && budgetUsd < COMMERCIAL_FLOOR_USD) {
  return [{
    json: {
      status: 'DISQUALIFIED',
      reason: `Budget $${budgetUsd} is below the strict $${COMMERCIAL_FLOOR_USD} commercial floor.`,
      domain: domain,
      qualification_score: 0,
      priority_tier: 'REJECTED',
      route: 'archive'
    }
  }];
}

// Calculate 0-100 ICP Scoring Rubric
let score = 50; // base score

// Health deficit opportunity: sites with problems need more agency services
if (healthScore < 60) score += 20;
else if (healthScore < 80) score += 10;

// Team capacity factor
if (teamSize >= 5 && teamSize <= 100) score += 15;
else if (teamSize > 100) score += 10;

// Budget bonus
if (budgetUsd >= 2000) score += 15;
else if (budgetUsd >= 1000) score += 10;

score = Math.min(100, Math.max(0, score));

let priority = 'LOW';
let route = 'nurture';
if (score >= 80) {
  priority = 'HIGH';
  route = 'immediate_outreach';
} else if (score >= 60) {
  priority = 'MEDIUM';
  route = 'standard_queue';
}

return [{
  json: {
    status: 'QUALIFIED',
    domain: domain,
    qualification_score: score,
    priority_tier: priority,
    estimated_budget_usd: budgetUsd || 1200,
    route: route,
    qualified_at: new Date().toISOString()
  }
}];
